method.description:
The service registered for [param type], or [code]null[/code].
[codeblock]
@onready var session: NetwSession = Netw.session(self)

func _ready() -> void:
    var game := session.service(MyGame) as MyGame
[/codeblock]

signal.description:
Emitted on every peer once the peer that was [param successor_was] has become the server at id [code]1[/code], and the old server, if it stayed, has become [param former_now].
[param former_now] is [code]0[/code] when the old server is gone, and its player leaves after this signal.
[codeblocks]
[gdscript]
func _ready() -> void:
    Netw.session(self).server_transferred.connect(on_server_transferred)

func on_server_transferred(successor_was: int, former_now: int) -> void:
    scoreboard.rename(successor_was, 1)
    if former_now != 0:
        scoreboard.rename(1, former_now)
[/gdscript]
[csharp]
public override void _Ready()
{
    Netw.Session(this).ServerTransferred += OnServerTransferred;
}

private void OnServerTransferred(long successorWas, long formerNow)
{
    scoreboard.Rename(successorWas, 1);
    if (formerNow != 0)
        scoreboard.Rename(1, formerNow);
}
[/csharp]
[/codeblocks]
What each client keeps of its world follows its own [member NetwSessionConfig.transfer_mode].
